def _check_timers(self, eventtime, busy):
    if eventtime < self._next_timer:
        if busy:
            return 0.
        if self._check_gc:
            gi = gc.get_count()
            if gi[0] >= 700:
                # Reactor looks idle and gc is due - run it
                gc_level = 0
                if gi[1] >= 10:
                    gc_level = 1
                    if gi[2] >= 10:
                        gc_level = 2
                self._last_gc_times[gc_level] = eventtime
                gc.collect(gc_level)
                return 0.
        return min(1., max(.001, self._next_timer - eventtime))
    # Keep the scan minimum local; callbacks may still lower _next_timer.
    never = self._next_timer = self.NEVER
    next_timer = never
    g_dispatch = self._g_dispatch
    for t in self._timers:
        waketime = t.waketime
        if eventtime >= waketime:
            t.waketime = never
            t.timer_is_running = True
            try:
                t.waketime = waketime = t.callback(eventtime)
            finally:
                t.timer_is_running = False
            if g_dispatch is not self._g_dispatch:
                self._next_timer = min(self._next_timer, next_timer, waketime)
                self._end_greenlet(g_dispatch)
                return 0.
        if waketime < next_timer:
            next_timer = waketime
    if next_timer < self._next_timer:
        self._next_timer = next_timer
    return 0.
